    regs_ok (ENV vals) srF0 R -> know_ok RSEGS (ENV vals) M knE ->
    rdn RSEGS M pp (length path + 1) = Some (path ++ [Z_to_bv 8 0]) ->
    atG0 path P T ->
    srealizes RSEGS scfg (mkCfg (mkst R (Z_to_bv 64 0xa17d8) M (seg_rom RSEGS)) model) T.
